/**
 * @file Live verification for the sites home window's Cmd+F find bar — the behaviour no unit test
 * in this package can reach, because what it pins is CHROMIUM's, not ours.
 *
 * Not part of `npm test`: it launches a real Electron app, so it is opt-in and slow. Run it after
 * touching anything in `src/renderer/use-find-in-page.hooks.ts`, `src/find-in-page-ipc.ts`,
 * `src/find-menu.ts` or `src/contracts/find-in-page.ts`:
 *
 *   cd apps/desktop
 *   npm run build:renderer            # the window loads dist/, never src/
 *   node scripts/verify-find-in-page.ts
 *   FIND_VERIFY_NATIVE_KEYS=1 node scripts/verify-find-in-page.ts   # + real OS keystrokes
 *
 * **Every CDP-typed check here is blind to the 2026-09-29 regression.** Playwright's `keyboard`
 * delivers keys to the page it targets, bypassing the browser's keyboard routing — so it passed
 * while the real app took one letter and sent the rest into the `<webview>` guest. Only the
 * opt-in `*_EVERY_NATIVE_KEYSTROKE_LANDS` checks (see `verifyNativeTyping`) exercise that routing.
 *
 * It always launches an ISOLATED instance with its own `TOVU_DESKTOP_USER_DATA_DIR`, so it never
 * touches a running app's session (this app takes no single-instance lock). Exits non-zero on the
 * first failed check and prints `FAIL::` lines; screenshots land in
 * `ADS-memory/.local-artifacts/find-enter-fix-screenshots-<date>/` unless `FIND_SHOT_DIR` says
 * otherwise.
 *
 * The load-bearing check is CHROMIUM_ANCHOR: a find issued while a caret sits in the find bar's own
 * input does NOT advance, and the same find issued with the document selection cleared DOES. That
 * is the platform behaviour `runFind`'s selection clearing exists to compensate for — if a future
 * Chromium stops anchoring on the live selection, this check fails loudly and the compensation can
 * go, rather than quietly becoming cargo cult.
 *
 * `verifyColdGuest` runs FIRST, before `verifyTopLevel` or `verifyGuest`, on a window that has not
 * run a single find yet — the one path those two phases never exercised (2026-09-18's live run
 * always warmed the window with `verifyTopLevel` first) and the one path the 2026-09-21 focus-loss
 * bug actually lived on. It types a multi-character query at human speed (80ms/key, not the other
 * phases' 350ms — see that function's own doc for why the gap matters) and checks
 * `document.hasFocus()` in addition to `activeElement`, because the bug leaves `activeElement`
 * still reporting the find input even after the page itself has lost focus.
 *
 * Every `BrowserWindow` lookup targets a `homeWindowId` captured once at startup, never
 * `BrowserWindow.getAllWindows()[0]`. `[0]` is the most-recently-CREATED window, not the app shell:
 * `main.ts`'s `captureSitePreview` opens a short-lived `show: false` window on every site start to
 * screenshot it for the project card, and that window outlives the few seconds `verifyColdGuest`
 * waits after a guest attaches. Sending the toggle to `[0]` during that overlap delivered it to the
 * hidden capture window instead — which renders the bare site page, no Tovu shell, so the find bar
 * never opened and every later assertion in the phase failed. Reproduced live, twice, with
 * `BrowserWindow.getAllWindows()` logged at the point of failure: `[{id:2, visible:false, title:
 * "<the site's own title>"}, {id:1, visible:true, title:"Tovu"}]`. `verifyGuest`'s later, warm run
 * never hit this because by then the capture window from its own site's start had long since closed.
 */
import { _electron as electron } from 'playwright';
import type { ElectronApplication, Page } from 'playwright';
import path from 'node:path';
import fs from 'node:fs';
import { execFileSync } from 'node:child_process';

import { createCheckLog } from '../src/live-verify-checks.ts';
import { advancesEveryStep, nextOrdinal, parseCount, previousOrdinal } from '../src/find-in-page-verify.ts';
import type { Count } from '../src/find-in-page-verify.ts';

const DESKTOP = path.resolve(import.meta.dirname, '..');
const REPO = path.resolve(DESKTOP, '../..');
const SHOT_DIR = process.env.FIND_SHOT_DIR ?? path.join(REPO, 'ADS-memory/.local-artifacts/find-enter-fix-screenshots-2026-09-18');
const USER_DATA = process.env.FIND_VERIFY_USERDATA ?? fs.mkdtempSync(path.join(process.env.TMPDIR ?? '/tmp', 'tovu-find-verify-'));

const { check, report } = createCheckLog({ log: (line) => console.log(line) });
let shotN = 0;

async function shot(win: Page, name: string): Promise<string> {
  shotN += 1;
  const file = path.join(SHOT_DIR, `${String(shotN).padStart(2, '0')}-${name}.png`);
  await win.screenshot({ path: file });
  return file;
}

const countText = (win: Page): Promise<string> =>
  win.evaluate(() => document.querySelector('.findbar__count')?.textContent ?? '');

/** The counter arrives asynchronously (`found-in-page` -> relay -> renderer), so the first read
 *  after typing has to wait for it rather than assume it has landed. */
async function waitForCount(win: Page, timeoutMs = 6000): Promise<Count | null> {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const parsed = parseCount(await countText(win));
    if (parsed !== null || Date.now() > deadline) return parsed;
    await win.waitForTimeout(250);
  }
}
const barOpen = (win: Page): Promise<boolean> => win.evaluate(() => !!document.querySelector('.findbar'));
const inputState = (win: Page): Promise<{ active: string; value: string | null }> =>
  win.evaluate(() => ({
    active: document.activeElement?.className || document.activeElement?.tagName || 'none',
    value: document.querySelector<HTMLInputElement>('.findbar__input')?.value ?? null,
  }));

/** Opens the bar the way the app menu does — `find-menu.ts` just sends this channel. A real
 *  `Meta+F` only reaches a menu accelerator when the app owns the OS focus, which a headed test
 *  run cannot assume. Targets `homeWindowId` — see this file's header — not `getAllWindows()[0]`. */
async function openBar(app: ElectronApplication, win: Page, homeWindowId: number): Promise<void> {
  await app.evaluate(
    ({ BrowserWindow }, id) => BrowserWindow.fromId(id)?.webContents.send('runner:find:toggle'),
    homeWindowId,
  );
  await win.waitForTimeout(600);
}

/** Types `text` one real key at a time with NO re-focus in between — the whole point: a search that
 *  blurs the input silently eats every character after the first, and `locator.fill()`/
 *  `locator.press()` both re-focus and would hide exactly that.
 *
 * @param msPerKey gap between keystrokes. The default 350ms is generous enough that a deferred
 *   focus-reclaim always wins its race before the next key, which is fine for the phases pinning
 *   OTHER behaviour (cycling, Escape, the Chromium anchor). `verifyColdGuest` passes a human-speed
 *   80ms instead, because that race is exactly what it exists to catch. */
async function typeQuery(win: Page, text: string, msPerKey = 350): Promise<void> {
  for (const character of text) {
    await win.keyboard.type(character);
    await win.waitForTimeout(msPerKey);
  }
}

/** Presses Enter `times` times with no re-focus, collecting the counter after each — and, when
 *  `shotName` is given, a screenshot per press, since "the counter advanced" is a claim worth
 *  being able to look at rather than take on trust. */
async function pressEnter(
  win: Page,
  times: number,
  { modifier = '', shotName = null }: { modifier?: string; shotName?: string | null } = {},
): Promise<(Count | null)[]> {
  const seen: (Count | null)[] = [];
  for (let i = 0; i < times; i += 1) {
    await win.keyboard.press(modifier ? `${modifier}+Enter` : 'Enter');
    await win.waitForTimeout(450);
    seen.push(parseCount(await countText(win)));
    if (shotName) await shot(win, `${shotName}-${i + 1}`);
  }
  return seen;
}

/** Enter cycles forward three times, then Shift+Enter steps back one — on whatever surface the bar
 *  is currently open over. */
async function verifyCycling(win: Page, start: Count): Promise<void> {
  const forward = await pressEnter(win, 3, { shotName: 'projects-enter' });
  check('ENTER_ADVANCES', advancesEveryStep(start.ordinal, forward, start.total), `${start.ordinal} -> ${forward.map((s) => s?.ordinal).join(' -> ')} of ${start.total}`);
  const here = parseCount(await countText(win));
  const [back] = await pressEnter(win, 1, { modifier: 'Shift', shotName: 'projects-shift-enter' });
  const expectedBack = previousOrdinal(here);
  check('SHIFT_ENTER_GOES_BACK', back != null && back.ordinal === expectedBack, `${here?.ordinal} -> ${back?.ordinal} (expected ${expectedBack}) of ${here?.total}`);
}

/** Re-focuses the find input, optionally clears the document selection, issues a raw
 *  `findInPage(findNext: false)` and returns the counter before and after. */
async function rawFindFromInput(
  app: ElectronApplication,
  win: Page,
  homeWindowId: number,
  { query, clearSelection }: { query: string; clearSelection: boolean },
): Promise<{ before: Count | null; after: Count | null }> {
  await win.evaluate(() => document.querySelector<HTMLInputElement>('.findbar__input')?.focus());
  await win.waitForTimeout(250);
  const before = parseCount(await countText(win));
  if (clearSelection) await win.evaluate(() => document.getSelection()?.removeAllRanges());
  await app.evaluate(
    ({ BrowserWindow }, { id, findText }) => {
      BrowserWindow.fromId(id)?.webContents.findInPage(findText, { forward: true, findNext: false });
    },
    { id: homeWindowId, findText: query },
  );
  await win.waitForTimeout(500);
  return { before, after: parseCount(await countText(win)) };
}

/** CHROMIUM_ANCHOR: the platform behaviour the fix compensates for, pinned both ways. */
async function verifyChromiumAnchor(app: ElectronApplication, win: Page, homeWindowId: number, query: string): Promise<void> {
  const anchored = await rawFindFromInput(app, win, homeWindowId, { query, clearSelection: false });
  check(
    'CHROMIUM_ANCHOR_STILL_BITES',
    anchored.after !== null && anchored.after.ordinal !== nextOrdinal(anchored.before),
    `caret in the input: ${anchored.before?.ordinal} -> ${anchored.after?.ordinal} (a plain follow-up find must NOT advance; if it does, Chromium changed and runFind's selection clearing can go)`,
  );

  const cleared = await rawFindFromInput(app, win, homeWindowId, { query, clearSelection: true });
  check(
    'CLEARING_THE_SELECTION_IS_WHAT_FIXES_IT',
    cleared.after !== null && cleared.after.ordinal === nextOrdinal(cleared.before),
    `selection cleared first: ${cleared.before?.ordinal} -> ${cleared.after?.ordinal} of ${cleared.before?.total}`,
  );
}

/**
 * Types `text` as REAL macOS keystrokes (System Events), not CDP. Playwright's `keyboard.type` sends
 * CDP `Input.dispatchKeyEvent` straight to the page it targets, so it lands in the find input even
 * when the BROWSER's keyboard routing has moved into a `<webview>` guest — which is exactly the
 * state the 2026-09-29 regression left the app in, and why every CDP-typed check here passed while
 * the owner could type one letter. Only an OS keystroke goes through that routing.
 *
 * Needs the terminal running this script to hold macOS Accessibility permission; without it
 * `osascript` fails and the phase reports FAIL (never a silent skip). Before EVERY key it re-checks
 * that the app under test is still the focused app, and stops typing if not, so a stray click
 * elsewhere cannot send these keystrokes into some other application.
 *
 * @returns `false` when the keys could not be delivered (no permission, or focus left the app).
 */
async function typeNative(app: ElectronApplication, win: Page, homeWindowId: number, text: string, msPerKey: number): Promise<{ ok: boolean; why: string }> {
  await app.evaluate(({ app: electronApp, BrowserWindow }, id) => {
    electronApp.focus({ steal: true });
    BrowserWindow.fromId(id)?.focus();
  }, homeWindowId);
  await win.waitForTimeout(300);
  for (const character of text) {
    const stillOurs = await app.evaluate(({ BrowserWindow }, id) => BrowserWindow.getFocusedWindow()?.id === id, homeWindowId);
    if (!stillOurs) return { ok: false, why: 'the app under test lost OS focus mid-typing; stopped rather than type into another app' };
    try {
      execFileSync('osascript', ['-e', `tell application "System Events" to keystroke ${JSON.stringify(character)}`]);
    } catch (error) {
      return { ok: false, why: `osascript could not send a keystroke (Accessibility permission?): ${String(error).split('\n')[0]}` };
    }
    await win.waitForTimeout(msPerKey);
  }
  return { ok: true, why: '' };
}

/**
 * Opens the bar, types a MULTI-character query with REAL OS keystrokes at `msPerKey` (see
 * {@link typeNative}), checks every character landed, then closes the bar. The cycling phases type
 * a single CDP `'e'`, which can tell neither "every keystroke lands" from "only the first does" nor
 * the host's own view of focus from where the browser actually routes keys.
 *
 * OPT-IN: runs only with `FIND_VERIFY_NATIVE_KEYS=1`, and prints SKIP (never PASS) otherwise.
 * Real keystrokes go to whatever app is frontmost at the instant they are sent; {@link typeNative}
 * re-checks focus before every key, but that check and the keystroke are not atomic, so on a machine
 * someone is using, a focus change in between can type the query into THEIR app. Run it when
 * nobody is at the keyboard.
 */
async function verifyNativeTyping(
  app: ElectronApplication,
  win: Page,
  homeWindowId: number,
  { label, query, msPerKey }: { label: string; query: string; msPerKey: number },
): Promise<void> {
  if (process.env.FIND_VERIFY_NATIVE_KEYS !== '1') {
    console.log(`SKIP:: ${label}_EVERY_NATIVE_KEYSTROKE_LANDS — set FIND_VERIFY_NATIVE_KEYS=1 to run (sends real OS keystrokes)`);
    return;
  }
  await openBar(app, win, homeWindowId);
  const typed = await typeNative(app, win, homeWindowId, query, msPerKey);
  await win.waitForTimeout(500);
  const afterTyping = await inputState(win);
  check(
    `${label}_EVERY_NATIVE_KEYSTROKE_LANDS`,
    typed.ok && afterTyping.value === query,
    typed.ok
      ? `input value = ${JSON.stringify(afterTyping.value)}, typed ${JSON.stringify(query)} as OS keystrokes at ${msPerKey}ms/key — "${query[0]}" alone means the browser routed every later key into the guest`
      : typed.why,
  );
  await shot(win, `${label.toLowerCase()}-native-typed`);
  await win.keyboard.press('Escape');
  await win.waitForTimeout(400);
}

async function verifyTopLevel(app: ElectronApplication, win: Page, homeWindowId: number): Promise<void> {
  await shot(win, 'projects-before-find');
  await verifyNativeTyping(app, win, homeWindowId, { label: 'TOP', query: 'website', msPerKey: 150 });
  await openBar(app, win, homeWindowId);
  check('BAR_OPENS', await barOpen(win), 'find bar present after the menu channel fired');

  // A query with several matches on the Projects screen. 'e' is deliberately unambitious: what is
  // under test is cycling, not matching.
  const query = 'e';
  await typeQuery(win, query);
  const afterTyping = await inputState(win);
  check('INPUT_KEEPS_FOCUS', afterTyping.active === 'findbar__input', `activeElement after typing = ${afterTyping.active}`);
  check('EVERY_KEYSTROKE_LANDS', afterTyping.value === query, `input value = ${JSON.stringify(afterTyping.value)}, typed ${JSON.stringify(query)}`);

  const start = await waitForCount(win);
  const enoughMatches = start !== null && start.total >= 3;
  check('COUNTER_SHOWS_MATCHES', enoughMatches, `counter = ${JSON.stringify(await countText(win))}`);
  await shot(win, 'projects-typed');
  if (start === null || !enoughMatches) return;

  await verifyCycling(win, start);
  await verifyChromiumAnchor(app, win, homeWindowId, query);

  await win.keyboard.press('Escape');
  await win.waitForTimeout(400);
  check('ESCAPE_CLOSES', !(await barOpen(win)), 'find bar gone after Escape');
  await shot(win, 'projects-after-escape');
}

/** Opens the first openable project card and waits for its `<webview>` guest to attach with a real
 *  `src`. Shared by the cold and warm guest phases, so neither duplicates the start-button/attach
 *  poll. `available: false` means there was no card to click at all — a different failure from
 *  `attached: false` (a card existed but its guest never came up). */
async function openGuestTab(win: Page): Promise<{ available: boolean; attached: boolean }> {
  const card = win.locator('.card.is-openable').first();
  if ((await card.count()) === 0) return { available: false, attached: false };
  await card.click();
  // A tab whose site server is not running yet shows a Start affordance first; it takes a moment
  // to render, so poll for it rather than assuming it is already there.
  const startButton = win.getByRole('button', { name: /^start site$/i });
  for (let i = 0; i < 12; i += 1) {
    await win.waitForTimeout(1000);
    if ((await startButton.count()) > 0) {
      await startButton.first().click();
      break;
    }
  }

  let attached = false;
  for (let i = 0; i < 60; i += 1) {
    attached = await win.evaluate(() => {
      const guest = document.querySelector<HTMLElement & { src: string }>('webview');
      return !!guest && !!guest.getAttribute('src') && guest.src !== 'about:blank';
    });
    if (attached) break;
    await win.waitForTimeout(2000);
  }
  return { available: true, attached };
}

/**
 * The COLD guest path — the bug the owner actually hit. Must run FIRST, before any find has been
 * issued on this window: once the window itself has run one find (`verifyTopLevel`'s Cmd+F on the
 * Projects screen), Chromium reroutes every later guest find to the WINDOW's own find manager, and
 * it is specifically the guest's OWN find manager — the one serving THIS phase — whose result used
 * to restore no focus at all (see `use-find-in-page.hooks.ts`'s file header).
 *
 * `document.hasFocus()` is checked alongside `activeElement`, because `activeElement` alone did not
 * catch this regression: the bug leaves the host document still reporting the find input as its
 * active element even after Chromium has moved keyboard focus into the guest frame.
 */
async function verifyColdGuest(app: ElectronApplication, win: Page, homeWindowId: number): Promise<void> {
  const { available, attached } = await openGuestTab(win);
  check('COLD_GUEST_TAB_AVAILABLE', available, 'an openable project card exists in this profile');
  if (!available) return;
  check('COLD_GUEST_ATTACHED', attached, 'a project tab webview attached with a real src, before any find has run on this window');
  if (!attached) return;
  await win.waitForTimeout(6000);
  await shot(win, 'cold-tab-loaded');

  await openBar(app, win, homeWindowId);
  check('COLD_GUEST_BAR_OPENS', await barOpen(win), 'find bar present over the project tab, window still cold');

  // 'the' rather than a site-specific word like 'site': it must be a query this test can trust to
  // MATCH regardless of which project fixture the profile happens to have (measured "No results"
  // for 'site' against the real tovu-com fixture's rendered text) — a near-universal English word,
  // still multi-character, still exercises the same one-letter-then-nothing regression.
  const query = 'the';
  await typeQuery(win, query, 80);
  const afterTyping = await inputState(win);
  const hasFocus = await win.evaluate(() => document.hasFocus());
  check('COLD_GUEST_INPUT_KEEPS_FOCUS', afterTyping.active === 'findbar__input', `activeElement after typing = ${afterTyping.active}`);
  check(
    'COLD_GUEST_EVERY_KEYSTROKE_LANDS',
    afterTyping.value === query,
    `input value = ${JSON.stringify(afterTyping.value)}, typed ${JSON.stringify(query)} — a cold guest focus theft used to drop every letter after the first`,
  );
  check(
    'COLD_GUEST_DOCUMENT_HAS_FOCUS',
    hasFocus,
    `document.hasFocus() = ${hasFocus} — activeElement alone does not catch a guest theft, since the host keeps reporting the input as active even after losing page focus`,
  );
  await shot(win, 'cold-tab-typed');

  const start = await waitForCount(win);
  check('COLD_GUEST_COUNTER_SHOWS_MATCHES', start !== null && start.total >= 1, `counter = ${JSON.stringify(await countText(win))}`);
  if (start === null) return;

  const forward = await pressEnter(win, 1, { shotName: 'cold-tab-enter' });
  check(
    'COLD_GUEST_ENTER_ADVANCES',
    advancesEveryStep(start.ordinal, forward, start.total),
    `${start.ordinal} -> ${forward.map((s) => s?.ordinal).join(' -> ')} of ${start.total}`,
  );

  await win.keyboard.press('Escape');
  await win.waitForTimeout(400);
  check('COLD_GUEST_ESCAPE_CLOSES', !(await barOpen(win)), 'find bar gone after Escape');

  // Back to the Projects screen so `verifyTopLevel` and `verifyGuest` start from the surface they
  // expect — the only route home (see `App.tsx`'s `TabStrip` doc: the "All" tab is not closable by
  // design). Polls for the grid to actually be back rather than a flat sleep: a fixed 400ms
  // measured as too short for `showSitesHome` to flip and `SiteGrid` to re-render its cards,
  // leaving `verifyGuest`'s own `GUEST_TAB_AVAILABLE` finding a still-transitioning, cardless grid.
  await win.locator('.tab--sites-home').click();
  for (let i = 0; i < 10; i += 1) {
    if ((await win.locator('.card.is-openable').count()) > 0) break;
    await win.waitForTimeout(300);
  }
}

async function verifyGuest(app: ElectronApplication, win: Page, homeWindowId: number): Promise<void> {
  const { available, attached } = await openGuestTab(win);
  check('GUEST_TAB_AVAILABLE', available, 'an openable project card exists in this profile — the guest path went unverified');
  if (!available) return;
  check('GUEST_ATTACHED', attached, 'a project tab webview attached with a real src');
  if (!attached) return;
  await win.waitForTimeout(6000);
  await shot(win, 'tab-loaded');

  await verifyNativeTyping(app, win, homeWindowId, { label: 'GUEST', query: 'the', msPerKey: 150 });

  await openBar(app, win, homeWindowId);
  check('GUEST_BAR_OPENS', await barOpen(win), 'find bar present over the project tab');

  // WHERE a guest's find is reported is Chromium's choice, not ours, and it is not stable:
  // `WebContents::GetFindRequestManager` walks up the outer-WebContents chain and reuses the first
  // manager it finds, so once this WINDOW has run one find (the top-level phase above did), every
  // later guest find is served by the window's manager and reported on the window's own
  // `found-in-page` instead of the `<webview>`'s. Measured here, both ways. So counting window
  // results proves nothing about routing — what matters is that the guest's CONTENT was searched,
  // which the match total below establishes: the Projects screen alone reports ~12 for this query.
  await app.evaluate(({ BrowserWindow }, id) => {
    const contents = BrowserWindow.fromId(id)?.webContents;
    const counter = globalThis as { __topLevelFinds?: number };
    counter.__topLevelFinds = 0;
    contents?.on('found-in-page', () => {
      counter.__topLevelFinds = (counter.__topLevelFinds ?? 0) + 1;
    });
  }, homeWindowId);

  const query = 'e';
  await typeQuery(win, query);
  const afterTyping = await inputState(win);
  check('GUEST_INPUT_KEEPS_FOCUS', afterTyping.active === 'findbar__input', `activeElement after typing = ${afterTyping.active}`);
  check('GUEST_EVERY_KEYSTROKE_LANDS', afterTyping.value === query, `input value = ${JSON.stringify(afterTyping.value)}`);

  const start = await waitForCount(win);
  check('GUEST_COUNTER_SHOWS_MATCHES', start !== null && start.total >= 3, `counter = ${JSON.stringify(await countText(win))}`);
  await shot(win, 'tab-typed');
  if (start === null || start.total < 3) return;

  const forward = await pressEnter(win, 3, { shotName: 'tab-enter' });
  check('GUEST_ENTER_ADVANCES', advancesEveryStep(start.ordinal, forward, start.total), `${start.ordinal} -> ${forward.map((s) => s?.ordinal).join(' -> ')} of ${start.total}`);
  const topLevelFinds = await app.evaluate(() => (globalThis as { __topLevelFinds?: number }).__topLevelFinds ?? -1);
  const here = parseCount(await countText(win));
  check(
    'GUEST_CONTENT_IS_SEARCHED',
    here !== null && here.total > 30,
    `${here?.total} matches over the tab (the Projects screen alone reports ~12 for this query, so a search that reached only the shell would land there); the window's own webContents reported ${topLevelFinds} of these results, which is Chromium's find-manager reuse, not a routing fallback`,
  );
}

/** Waits (bounded) for the shell to render any text at all before the phases start. */
async function waitForShellText(win: Page): Promise<void> {
  for (let i = 0; i < 30; i += 1) {
    if ((await win.evaluate(() => document.body.innerText)).trim().length > 0) return;
    await win.waitForTimeout(800);
  }
}

async function main(): Promise<void> {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  fs.mkdirSync(USER_DATA, { recursive: true });
  console.log('USER_DATA::', USER_DATA);
  console.log('SHOT_DIR::', SHOT_DIR);

  const app = await electron.launch({
    executablePath: path.join(DESKTOP, 'node_modules/electron/dist/Electron.app/Contents/MacOS/Electron'),
    args: ['.'],
    cwd: DESKTOP,
    env: { ...process.env, TOVU_DESKTOP_USER_DATA_DIR: USER_DATA },
  });
  try {
    const win = await app.firstWindow();
    win.on('pageerror', (error) => console.log('PAGEERROR::', error.message));
    await win.waitForLoadState('domcontentloaded');
    await waitForShellText(win);
    // Captured once, here, while this is still the only window — see this file's header doc for why
    // every later `BrowserWindow` lookup targets this id instead of `getAllWindows()[0]`.
    const homeWindowId = await app.evaluate(({ BrowserWindow }) => BrowserWindow.getAllWindows()[0]?.id ?? -1);
    const includeGuest = process.env.FIND_VERIFY_SKIP_GUEST !== '1';
    if (includeGuest) await verifyColdGuest(app, win, homeWindowId);
    await verifyTopLevel(app, win, homeWindowId);
    if (includeGuest) await verifyGuest(app, win, homeWindowId);
  } finally {
    await app.close();
  }

  process.exitCode = report();
}

main().catch((error: unknown) => {
  console.error('SCRIPT_FAILED::', error);
  process.exitCode = 1;
});

/**
 * @file Live verification for a site card's Start/Stop button and its action row — the behaviour no
 * unit test in this package can reach, because it ends in a real `tovu serve` being spawned and
 * drained.
 *
 * **Revision (2026-09-18):** delete moved OFF the card and into the ⋮ menu — the owner's own reason
 * is misclicks, a destructive control beside a button pressed often. Only the ⋮ trigger is now
 * always-visible without hovering; the trash is checked ABSENT at top level and present only once
 * the menu is opened, and a click through it still lands on the same confirm overlay rather than
 * deleting directly. Start/Stop was also restyled to the header's "Create website" look
 * (`.button--create`), checked here by comparing computed styles rather than trusting a class name.
 *
 * **Second revision, same day.** The owner moved the controls again after seeing that layout: the
 * ⋮ to the card's top-right, level with the site name, and Start/Stop directly beneath it. The
 * card body is two columns now (`.card__info` and `.jini-site-card__actions`). Everything above still holds —
 * nothing about what either control DOES changed — and `LAYOUT_*` below adds the three geometric
 * claims that only a laid-out window can settle, read from `getBoundingClientRect` rather than from
 * pixels: a screenshot cannot tell a right-aligned column from one that merely looks flush.
 *
 * **Third revision (2026-10-06).** The ⋮ stays level with the name, but Start/Stop moved to the
 * LEFT, on its own row under the text (the "SQLite" line), with Restart on that row's right edge.
 * `sharedRightEdge` (⋮ and Start/Stop on one right edge) is therefore replaced by `powerUnderText`:
 * Start/Stop's left edge on the text column's, and its top below the text.
 *
 * **Fourth revision, same day.** The status moved under the ⋮ on the right and "SQLite" sits
 * directly under the name; `.card__info` is gone (the head is a 2x2 grid). `powerBelowMenu` became
 * `statusUnderMenu`, and the text-column box became the `.jini-site-card__details` and `.jini-site-card__meta` boxes.
 *
 * Not part of `npm test`: it launches a real Electron app and a real site server, so it is opt-in
 * and slow. Run it after touching `src/renderer/use-site-power.hooks.ts`, `src/renderer/SiteGrid.tsx`,
 * `src/project-ipc.ts`'s `handleStart`/`handleStop`, or `src/site-transitions.ts`:
 *
 *   cd apps/desktop
 *   npm run build:renderer                       # the window loads dist/, never src/
 *   SITE_POWER_SITE_DIR=<a real Tovu site> node scripts/verify-site-power.ts
 *
 * It always launches an ISOLATED instance with its own `TOVU_DESKTOP_USER_DATA_DIR`, so it never
 * touches a running app's session (this app takes no single-instance lock), and it SEEDS that
 * profile's `desktop-projects.json` itself — a fresh profile has no projects and no scan would find
 * one outside the scan roots, so without the seed the Websites screen is simply empty.
 *
 * `SITE_POWER_SITE_DIR` must be a site nothing else is serving. The site it names really is booted
 * and really is stopped; pointing it at a site another app instance has open would leave two
 * `tovu serve` children on one content.db.
 *
 * Screenshots land in `ADS-memory/.local-artifacts/site-card-actions-screenshots-<date>/` unless
 * `SITE_POWER_SHOT_DIR` says otherwise. Exits non-zero on the first failed check.
 */
import { _electron as electron } from 'playwright';
import type { ElectronApplication, Page } from 'playwright';
import path from 'node:path';
import fs from 'node:fs';

import { createCheckLog } from '../src/live-verify-checks.ts';
import { allLayoutClaimsHold, flat, layoutClaims, seedSitePowerProfile } from '../src/site-power-verify.ts';
import type { Box, CardState, LayoutClaims } from '../src/site-power-verify.ts';

const DESKTOP = path.resolve(import.meta.dirname, '..');
const REPO = path.resolve(DESKTOP, '../..');
const SHOT_DIR =
  process.env.SITE_POWER_SHOT_DIR ??
  path.join(REPO, 'ADS-memory/.local-artifacts/site-card-actions-v2-screenshots-2026-09-18');
const USER_DATA =
  process.env.SITE_POWER_USERDATA ?? fs.mkdtempSync(path.join(process.env.TMPDIR ?? '/tmp', 'tovu-site-power-'));
const SITE_DIR = process.env.SITE_POWER_SITE_DIR;

const { check, report } = createCheckLog({ log: (line) => console.log(line) });
let shotN = 0;

async function shot(win: Page, name: string): Promise<string> {
  shotN += 1;
  const file = path.join(SHOT_DIR, `${String(shotN).padStart(2, '0')}-${name}.png`);
  await win.screenshot({ path: file });
  console.log(`SHOT:: ${file}`);
  return file;
}

/** Everything the first card is currently saying, read straight off the DOM. The small helpers are
 *  declared INSIDE the evaluated function because Playwright serializes it into the page, where
 *  nothing from this module's scope exists. */
const cardState = (win: Page): Promise<CardState | null> =>
  win.evaluate((): CardState | null => {
    const card = document.querySelector('.card');
    if (!card) return null;
    const text = (sel: string): string | null => card.querySelector(sel)?.textContent?.trim() ?? null;
    const has = (sel: string): boolean => card.querySelector(sel) !== null;
    const visible = (el: Element | null): boolean => {
      if (!el) return false;
      const style = getComputedStyle(el);
      return style.display !== 'none' && style.visibility !== 'hidden' && Number(style.opacity) > 0.01;
    };
    // `null` for anything absent so a missing element reads as a failed check rather than a thrown
    // script.
    const box = (sel: string): Box | null => {
      const el = card.querySelector(sel);
      if (!el) return null;
      const b = el.getBoundingClientRect();
      return { top: b.top, right: b.right, bottom: b.bottom, left: b.left };
    };
    const power = card.querySelector<HTMLButtonElement>('.card__power');
    return {
      className: card.className,
      // Which site this card is actually about. Read so the run can prove, BEFORE it clicks Start,
      // that the card it is driving is the scratch site it seeded — see `CARD_IS_SEEDED_SITE`.
      name: text('.jini-site-card__name'),
      status: text('.jini-site-card__status') ?? '',
      port: text('.card__port'),
      power: power ? { label: (power.textContent ?? '').trim(), disabled: power.disabled, visible: visible(power) } : null,
      // The one control the owner asked to be visible without hovering, now that delete no longer
      // sits beside it. Read WITHOUT any pointer over the card, which is the whole claim being
      // checked.
      menuVisible: visible(card.querySelector('.card__menubutton')),
      menuInTile: has('.jini-site-card__tile .card__menu'),
      // Must be absent at the TOP level of the card — delete lives only inside the closed ⋮ menu.
      trashOnCard: has('.card__delete'),
      actionsInBody: has('.jini-site-card__body .jini-site-card__actions'),
      // The owner's layout, as boxes.
      layout: { name: box('.jini-site-card__name'), menu: box('.card__menubutton'), power: box('.card__power'), details: box('.jini-site-card__details'), status: box('.jini-site-card__meta') },
      error: text('.card__actionerror'),
    };
  });

/** Computed style of the card's power button versus the header's "Create website" button — the
 *  live proof that Start/Stop actually wears that style rather than merely sharing a class name
 *  that some other rule overrides. */
const powerMatchesCreate = (win: Page) =>
  win.evaluate(() => {
    const power = document.querySelector('.card__power');
    const create = document.querySelector('.button--create');
    if (!power || !create) {
      return { found: false, sameBackground: false, sameBorderColor: false, sameFontWeight: false, powerBg: 'absent', createBg: 'absent' };
    }
    const p = getComputedStyle(power);
    const c = getComputedStyle(create);
    return {
      found: true,
      sameBackground: p.backgroundColor === c.backgroundColor,
      sameBorderColor: p.borderColor === c.borderColor,
      sameFontWeight: p.fontWeight === c.fontWeight,
      powerBg: p.backgroundColor,
      createBg: c.backgroundColor,
    };
  });

/** Poll until the card's status label reads `want`, or give up. Returns the last state seen. */
async function waitForStatus(win: Page, want: string, timeoutMs: number): Promise<CardState | null> {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const last = await cardState(win);
    if (last?.status === want || Date.now() > deadline) return last;
    await win.waitForTimeout(250);
  }
}

async function setTheme(win: Page, theme: string): Promise<void> {
  await win.evaluate((value) => localStorage.setItem('tovu-runner.theme', value), theme);
  await win.reload();
  await win.waitForSelector('.card', { timeout: 20_000 });
  await win.waitForTimeout(400);
}

/** Reads the first card and refuses to go on unless it is the seeded site. Throws — ending the
 *  run — when it is not.
 *
 * Every check after this reads `document.querySelector('.card')` — the FIRST card — and this script
 * goes on to really start and really stop whatever site that card is about. The seeded profile is
 * not the only thing that puts cards on this screen: `rescanSites` adopts every site under the
 * app's scan roots at boot, which on a dev checkout means the repo's own `sites/` — the operator's
 * real site, very possibly already being served by their own running app. Two `tovu serve`
 * children on one content.db is not a thing to discover from a screenshot afterwards, so the run
 * stops here rather than clicking Start on a card it cannot name. */
async function requireSeededCard(win: Page, expectedSiteName: string): Promise<CardState> {
  const idle = await cardState(win);
  const seen = flat(idle);
  check('CARD_SEEDED', idle !== null, `card rendered, status ${seen.status}`);
  check(
    'CARD_IS_SEEDED_SITE',
    seen.name === expectedSiteName,
    `first card is "${seen.name}", seeded site's config.json says "${expectedSiteName}"`,
  );
  if (idle === null || idle.name !== expectedSiteName) {
    throw new Error(
      `refusing to drive a card this run did not seed: first card is "${seen.name}", expected "${expectedSiteName}" (${SITE_DIR})`,
    );
  }
  return idle;
}

/** The three `LAYOUT_*` checks for one card state. */
function checkLayout(claims: LayoutClaims): void {
  check('LAYOUT_KEBAB_ON_NAME_ROW', claims.onNameRow.ok, claims.onNameRow.why);
  check('LAYOUT_POWER_UNDER_TEXT', claims.powerUnderText.ok, claims.powerUnderText.why);
  check('LAYOUT_STATUS_UNDER_KEBAB', claims.statusUnderMenu.ok, claims.statusUnderMenu.why);
}

/** The stopped card, before anything is clicked: it is the seeded site, its controls sit where the
 *  owner put them, and Start wears the "Create website" style. */
async function verifyIdleCard(win: Page, expectedSiteName: string): Promise<void> {
  const idle = await requireSeededCard(win, expectedSiteName);
  check(
    'ACTIONS_IN_BODY',
    idle.actionsInBody && !idle.menuInTile,
    `actions row in the info block (menu on preview: ${idle.menuInTile})`,
  );
  check('ALWAYS_VISIBLE', idle.menuVisible, `⋮ visible ${idle.menuVisible} — with no pointer over the card`);
  check(
    'NO_TOP_LEVEL_TRASH',
    !idle.trashOnCard,
    `a standalone .card__delete exists on the card outside the ⋮ menu (${idle.trashOnCard})`,
  );
  checkLayout(layoutClaims(idle));
  const label = flat(idle).label;
  check('POWER_OFFERS_START', label === 'Start', `power button reads "${label}"`);
  const startStyle = await powerMatchesCreate(win);
  check(
    'POWER_MATCHES_CREATE_STYLE',
    startStyle.found && startStyle.sameBackground && startStyle.sameBorderColor && startStyle.sameFontWeight,
    `power bg ${startStyle.powerBg} vs create bg ${startStyle.createBg} (border match: ${startStyle.sameBorderColor}, weight match: ${startStyle.sameFontWeight})`,
  );
  await shot(win, 'light-stopped');
}

/** Clicks the power button and checks the mid-transition label (`Starting…`/`Stopping…`) and that
 *  the button is disabled while it lasts. */
async function clickPowerExpectingTransition(win: Page, checkName: string, label: string, verb: string): Promise<void> {
  await win.click('.card__power');
  const mid = flat(await cardState(win));
  check(
    checkName,
    mid.label === label && mid.disabled === true,
    `mid-${verb} the button reads "${mid.label}" (disabled: ${mid.disabled})`,
  );
}

/** Clicks Start and waits for Running; the card offers Stop and keeps its layout with the wider
 *  label in place. */
async function verifyStarted(win: Page): Promise<void> {
  await clickPowerExpectingTransition(win, 'START_SAYS_STARTING', 'Starting…', 'start');
  await shot(win, 'light-starting');

  const runningState = await waitForStatus(win, 'Running', 90_000);
  const running = flat(runningState);
  check('STARTED', running.status === 'Running', `status after start: ${running.status}`);
  check('POWER_OFFERS_STOP', running.label === 'Stop', `power button reads "${running.label}"`);
  // Re-read with the WIDER label in place: "Stop" is a bigger box than "Start", and a column that
  // only lines up around the narrow one is not right-aligned, it is coincidental.
  const runningLayout = layoutClaims(runningState);
  check(
    'LAYOUT_HOLDS_WITH_STOP',
    allLayoutClaimsHold(runningLayout),
    `with "Stop" — ${runningLayout.powerUnderText.why}; ${runningLayout.statusUnderMenu.why}`,
  );
  await shot(win, 'light-running');
}

/** Clicks Stop and waits for Stopped; the card offers Start again with no stale port or error. */
async function verifyStopped(win: Page): Promise<void> {
  await clickPowerExpectingTransition(win, 'STOP_SAYS_STOPPING', 'Stopping…', 'stop');
  await shot(win, 'light-stopping');

  const stopped = flat(await waitForStatus(win, 'Stopped', 30_000));
  check('STOPPED', stopped.status === 'Stopped', `status after stop: ${stopped.status}`);
  check('POWER_BACK_TO_START', stopped.label === 'Start', `power button reads "${stopped.label}"`);
  // The port is reassigned on every start, so a stopped card must not keep showing the one it had.
  check('NO_STALE_PORT', stopped.port == null || stopped.port === '0', `port fallback shows ${stopped.port}`);
  check('NO_ERROR', stopped.error == null, `no failure text on the card (${stopped.error})`);
  await shot(win, 'light-stopped-again');
}

/** New risk from the ⋮ moving to the TOP of the body: `.card` clips to its rounded corners, and
 *  the list opens upward over the preview tile. Too tall a list, or a trigger that drifts back
 *  down, and the top of the menu is silently cut off — a screenshot shows a shorter menu, not an
 *  obviously broken one, so this is read from boxes. */
async function checkMenuNotClipped(win: Page): Promise<void> {
  const menuClip = await win.evaluate(() => {
    const list = document.querySelector('.card__menulist');
    const card = document.querySelector('.card');
    if (!list || !card) return null;
    const l = list.getBoundingClientRect();
    const c = card.getBoundingClientRect();
    return { listTop: l.top, listBottom: l.bottom, cardTop: c.top, cardBottom: c.bottom };
  });
  check(
    'MENU_LIST_NOT_CLIPPED',
    menuClip !== null && menuClip.listTop >= menuClip.cardTop && menuClip.listBottom <= menuClip.cardBottom,
    menuClip === null
      ? 'no open menu list to measure'
      : `list ${menuClip.listTop.toFixed(1)}–${menuClip.listBottom.toFixed(1)} inside card ${menuClip.cardTop.toFixed(1)}–${menuClip.cardBottom.toFixed(1)}`,
  );
}

/** The seeded site is adopted (origin: 'adopted'), so its entry must read as the SAFE branch —
 *  plain text, not the danger styling erasing-file deletes get — and clicking it must still land
 *  on the confirm overlay rather than deleting straight away. Cancels, so the scratch site stays
 *  intact for any rerun of this script. */
async function verifyDeleteEntry(win: Page): Promise<void> {
  const deleteEntry = await win.evaluate(() => {
    const item = [...document.querySelectorAll('.card__menulist [role="menuitem"]')].find((el) =>
      /Delete|Remove from Projects/.test(el.textContent ?? ''),
    );
    return item ? { text: (item.textContent ?? '').trim(), danger: item.classList.contains('card__menuitem--danger') } : null;
  });
  check(
    'ADOPTED_SITE_ENTRY_NOT_DANGER_STYLED',
    deleteEntry?.text === 'Remove from Projects…' && !deleteEntry.danger,
    `entry "${deleteEntry?.text}", danger class present: ${deleteEntry?.danger}`,
  );
  await win.click('.card__menulist [role="menuitem"]:has-text("Remove from Projects")');
  const confirmShown = await win.evaluate(() => document.querySelector('.card__confirm') !== null);
  check('DELETE_ENTRY_OPENS_CONFIRM', confirmShown, 'clicking the menu entry must open the confirm overlay, not delete directly');
  await shot(win, 'light-menu-delete-confirm');
  await win.click('.card__confirmacts .button--quiet');
  const confirmDismissed = await win.evaluate(() => document.querySelector('.card__confirm') === null);
  check('CONFIRM_CANCEL_DISMISSES', confirmDismissed, 'Cancel must close the overlay without deleting');
}

/** Closes an open ⋮ menu the way a user would: Escape, then a click on empty page. */
async function closeMenu(win: Page): Promise<void> {
  await win.keyboard.press('Escape');
  await win.click('body', { position: { x: 5, y: 5 } });
}

/** The ⋮ menu still opens from its new home, and now carries delete. */
async function verifyMenu(win: Page): Promise<void> {
  await win.click('.card__menubutton');
  // The menu's background is theme-derived (`var(--surface)`), and screenshotting in the same
  // tick as the click can catch the freshly-mounted popover before that paints — a genuine paint
  // race, not a styling bug: `getComputedStyle` on it is correct even in the same tick a
  // screenshot taken then is not. The wait is for the SHOT below to be trustworthy, not for the
  // checks, which already read computed truth.
  await win.waitForTimeout(150);
  const menuItems = await win.evaluate(() =>
    [...document.querySelectorAll('.card__menulist [role="menuitem"]')].map((el) => (el.textContent ?? '').trim()),
  );
  check('MENU_OPENS', menuItems.length > 0, `menu items: ${menuItems.join(' | ')}`);
  await checkMenuNotClipped(win);
  check(
    'MENU_HAS_NO_LIFECYCLE',
    !menuItems.some((item) => item === 'Start' || item === 'Stop'),
    'neither Start nor Stop is duplicated in the ⋮ menu',
  );
  check(
    'MENU_HAS_DELETE_ENTRY',
    menuItems.some((item) => item === 'Delete…' || item === 'Remove from Projects…'),
    `menu items: ${menuItems.join(' | ')}`,
  );
  await shot(win, 'light-menu-open');
  await verifyDeleteEntry(win);
  await closeMenu(win);
}

/** Dark mode: the same controls stay visible and laid out, and the site still starts and stops. */
async function verifyDark(win: Page): Promise<void> {
  await setTheme(win, 'dark');
  const darkState = await cardState(win);
  const dark = flat(darkState);
  check(
    'DARK_ALWAYS_VISIBLE',
    dark.menuVisible === true && dark.trashOnCard === false && dark.hasPower === true,
    `dark mode: ⋮ ${dark.menuVisible}, top-level trash present ${dark.trashOnCard}, power "${dark.label}"`,
  );
  const darkLayout = layoutClaims(darkState);
  check('DARK_LAYOUT_HOLDS', allLayoutClaimsHold(darkLayout), `dark mode — ${darkLayout.onNameRow.why}`);
  await shot(win, 'dark-stopped');
  await win.click('.card__menubutton');
  await win.waitForTimeout(150); // see the identical wait in `verifyMenu` — the same paint race.
  await shot(win, 'dark-menu-open');
  await closeMenu(win);
  await win.click('.card__power');
  const darkRunning = flat(await waitForStatus(win, 'Running', 90_000));
  check('DARK_STARTED', darkRunning.status === 'Running', `dark mode status after start: ${darkRunning.status}`);
  await shot(win, 'dark-running');
  await win.click('.card__power');
  const darkStopped = flat(await waitForStatus(win, 'Stopped', 30_000));
  check('DARK_STOPPED', darkStopped.status === 'Stopped', `dark mode status after stop: ${darkStopped.status}`);
  await shot(win, 'dark-stopped-again');
}

function launchIsolatedApp(): Promise<ElectronApplication> {
  return electron.launch({
    executablePath: path.join(DESKTOP, 'node_modules/electron/dist/Electron.app/Contents/MacOS/Electron'),
    args: ['.'],
    cwd: DESKTOP,
    env: { ...process.env, TOVU_DESKTOP_USER_DATA_DIR: USER_DATA, TOVU_DESKTOP_UI: 'runner' },
  });
}

async function main(): Promise<void> {
  const expectedSiteName = seedSitePowerProfile({ siteDir: SITE_DIR, shotDir: SHOT_DIR, userDataDir: USER_DATA }, { fs, log: (line) => console.log(line), now: () => new Date() });
  if (expectedSiteName === null) {
    process.exitCode = 1;
    return;
  }

  const app = await launchIsolatedApp();
  try {
    const win = await app.firstWindow();
    win.on('pageerror', (error) => console.log('PAGEERROR::', error.message));
    await win.waitForLoadState('domcontentloaded');
    await win.waitForSelector('.card', { timeout: 30_000 });
    await verifyIdleCard(win, expectedSiteName);
    await verifyStarted(win);
    await verifyStopped(win);
    await verifyMenu(win);
    await verifyDark(win);
  } finally {
    await app.close();
  }

  process.exitCode = report();
}

await main();

import { SITE_SLEEP_EXIT_CODE } from "../../../website/src/assistant/daemon-exit-codes.ts";
import { migrateNestedSitesHome } from "../nested-sites-migration.ts";
import { createSitesWorkspace, rememberSharedSiteOpen, attachRunningSite } from "../shared-sites.ts";
/**
 * @file `apps/desktop` — an Electron shell around the SAME Tovu that `npm run dev` boots, now
 * multi-site: several sites can be open, each in its own window, each spawning its own `tovu serve`.
 *
 * This directory is deliberately additive and self-contained. Nothing outside it imports it,
 * nothing outside it references it, and `development/scripts/dev.mjs` is untouched — deleting
 * `apps/desktop/` returns the repo to exactly its previous state. That is the whole point: the
 * desktop mode is a second CONSUMER of the existing product, never a fork of it.
 *
 * Three boot modes, one product:
 *
 * 0. **Sites Home** — the DEFAULT since 2026-09-06. Opens Tovu-Runner's ported renderer
 *    (`src/renderer/`, built to `dist/renderer/index.html`) instead of any site's admin — its
 *    Projects screen, now the app's actual front page. Opening a project embeds it as a TAB in this
 *    SAME window, in a `<webview>` (`renderer/app/SiteWorkspace.tsx`), rather than popping it into its
 *    own `BrowserWindow` — matching Tovu-Runner's own tabbed UI, which is the reference this was
 *    built against. `list`/`create`/`delete`/`open-external`/`start` are real (`src/project-ipc.ts`),
 *    `start` routing a tab's first open through `openSiteServer`'s `serializer`-guarded spawn-or-reuse
 *    below (the sites-home counterpart of `openSiteWindow`, spawn-only, no window); `stop` stays a
 *    throwing stub — no control in the per-project bar calls it yet. See `sitesUiRequested`'s own doc
 *    for exactly which env vars bypass this default and fall through to modes 1/2 instead.
 *
 * 1. **Attach** (`TOVU_DESKTOP_URL` set). The window loads a stack someone else already started —
 *    normally the `npm run dev` pair (API on :3000, admin Vite on :5173). Nothing is spawned, so
 *    web mode and desktop mode run side by side against the same server. Single-site only — there
 *    is exactly one URL to attach to — and unrelated to everything else below. Bypasses the sites
 *    home UI unconditionally: an automation/dev workflow that already names its one destination has no
 *    use for a project picker.
 *
 * 2. **Own server** (`TOVU_DESKTOP_SITE_DIR` or `TOVU_DESKTOP_SITE_DIRS` set). Spawns Tovu's OWN
 *    `tovu serve <dir>` CLI as a child per open site and loads the port each one reports. `tovu
 *    serve` is already the packaged single-site entry point — it boots the site dir, opens
 *    `<dir>/content.db`, wires the admin SPA and starts the agent daemon
 *    (`apps/website/src/cli/commands/serve.ts`). The shell therefore needs no Tovu-side change to
 *    open a second, third, or Nth site: `src/tovu-server.ts`'s `startTovuServer` was already a
 *    pure `{repoRoot, siteDir, port} -> handle` function with no single-instance assumption
 *    anywhere in it. Also bypasses the sites home UI unconditionally, same reasoning as attach mode —
 *    this is what keeps every `TOVU_DESKTOP_SITE_DIR`-driven E2E spec and any other automation
 *    byte-for-byte unaffected by the sites home UI becoming the default.
 *
 * **Multi-site, concretely (own-server/attach modes):**
 * - `openSites` (a `Map<siteDir, {server, window?}>`) replaces the old single `tovuServer` variable.
 *   The sites home UI (mode 0) shares this same map but never sets `window` — see `openSiteServer`.
 * - Each open site gets its own `BrowserWindow`, titled with the site's own name — Electron's native
 *   `role: "windowMenu"` (macOS) then lists every open window and switches between them for free.
 *   That IS the site switcher: no custom panel was needed, every open site is just another window.
 *   The sites home UI's own switcher is its tab strip instead (`renderer/app/TabStrip.tsx`) — one window, N tabs.
 * - "Open Site…" (File menu) runs the folder picker for a NEW site, independent of whichever sites
 *   are already open. "Open Recent" lists `site-dir-store.ts`'s existing MRU.
 * - `keyed-serializer.ts` serializes opens PER SITE DIR, so a fast double-click on the same recent-
 *   site menu entry cannot double-spawn a `tovu serve` for it (Tovu-Runner's `serializeByProject`
 *   pattern, generalized).
 *
 * **Crash-safety**, now in scope (`site-process-registry.ts`): every open site's `{siteDir, port,
 * workspaceId, pid}` is persisted to a small JSON registry the moment its `tovu serve` reports ready,
 * and removed the moment it is stopped deliberately (a window closed on Windows/Linux, or the app
 * quit cleanly). macOS window close retains the server and registry until an explicit stop/quit. If
 * Electron itself is hard-killed (SIGKILL, a crash, a forced logout) before that removal runs, the
 * NEXT launch's `reconcileOrphans()` finds the stale row, proves the pid is STILL that row's own
 * `tovu serve` (identity-before-kill — see that file's own header), and terminates it before any
 * window opens. This was `main.js`'s own prior comment's deferred item: "that machinery belongs
 * with the fleet supervisor... reported rather than ported." It is now built, sized to what this
 * shell actually needs (not Tovu-Runner's full fleet registry). That reconciliation runs for EVERY
 * boot mode ({@link reconcileOrphansOnBoot}, above the mode split); it lived inside own-server mode
 * alone until 2026-09-06, which left the sites home UI — the default, and the mode that actually produces
 * these rows — leaking a stranded child per open site on every hard kill.
 *
 * **The `dist/` schema-skew fix**: own-server mode now runs the CLI's own TypeScript source under
 * `--import tsx` by default (`TOVU_DESKTOP_CLI_MODE=source`), not the compiled `dist/` this
 * checkout's `bin.tovu` names. `dist/src/cli/main.js` here was last built 2026-08-28 (schema v50);
 * current source is v57 — own-server mode rejected every site created from current source with
 * `SITE_NEWER_THAN_RUNTIME`. Rebuilding `dist/` was not an option (`npm run build` is gated behind
 * `check-no-linked-jini.mjs`, and this checkout deliberately keeps 13 `@jini-ai/*` packages symlinked
 * to a local Jini checkout for active development); running the CLI from source instead — the same
 * way `development/scripts/dev.mjs` already runs `index.ts` under `npx tsx watch` — removes the skew
 * without touching the build or the Jini links. See `tovu-server.ts`'s `buildCliSpawnPlan` for the
 * mode's own default (unchanged, `"compiled"`, so every existing test keeps its exact prior
 * behavior) versus this file's production default (`"source"`, set here via the env var).
 *
 * `TOVU_DESKTOP_SELFTEST=1` makes the shell prove itself and exit instead of staying open: it
 * reports every opened window's URL and title, then quits 0 once all have loaded (1 on any failure).
 *
 * Environment:
 * - `TOVU_DESKTOP_UI`        — `"runner"` opens the ported sites home renderer explicitly (redundant
 *   with the default now, kept for anyone who has it set); any other non-empty value forces the
 *   pre-flip behavior even with no site-selecting env var set. See `sitesUiRequested`.
 * - `TOVU_DESKTOP_URL`       — attach to this origin instead of spawning any server (single-site);
 *   also bypasses the sites home UI default.
 * - `TOVU_DESKTOP_SITE_DIR`  — force a single site dir for own-server mode, skipping the picker;
 *   also bypasses the sites home UI default.
 * - `TOVU_DESKTOP_SITE_DIRS` — comma-separated site dirs to open at launch, one window each —
 *   bypasses the picker/MRU/dev-fallback precedence entirely, and the sites home UI default. Chiefly
 *   for verification/automation (proving N sites boot concurrently without driving the menu by
 *   hand); a real user reaches the
 *   same result through "Open Site…"/"Open Recent" after the first site opens.
 * - `TOVU_DESKTOP_PORT`      — pin the FIRST own-server site's port; every other open site still
 *   self-allocates (two sites must never collide).
 * - `TOVU_DESKTOP_CLI_MODE`  — `"source"` (default) or `"compiled"`; see the schema-skew note above.
 * - `TOVU_DESKTOP_SELFTEST`  — `1` to verify and exit rather than staying open.
 * - `TOVU_DESKTOP_USER_DATA_DIR` — E2E-only. Overrides `app.getPath("userData")`. Unset in every
 *   real launch — see the constant's own doc for why this exists instead of scoping `HOME`.
 */
