const PAYLOAD_ROOT = DESKTOP_ROOTS.payloadRoot;
const SELFTEST = process.env.TOVU_DESKTOP_SELFTEST === "1";

/**
 * The site a checkout always has and a packaged app never does — `bootOwnServerMode`'s last
